import os,re,subprocess,sys
DEV=os.path.expanduser('~/DEV')
envs=sys.argv[2:]
repos=[l.strip() for l in open(sys.argv[1]) if l.strip()]
vals={}
for e in envs:
    for line in open(os.path.join(DEV,e),errors='replace'):
        m=re.match(r'^([A-Za-z_][A-Za-z0-9_]*)=(.*)$',line.strip())
        if not m: continue
        k,v=m.group(1),m.group(2).strip().strip('"\'')
        if len(v)>=16 and not v.startswith(('http','/','~','C:')) and any(s in k for s in ('KEY','SECRET','TOKEN','PASSWORD','DATABASE_URL')):
            vals.setdefault(v,set()).add(f"{e}:{k}")
print(len(vals),"secret values")
hits=0
for v,src in vals.items():
    for r in repos:
        h=subprocess.run(['git','-C',r,'grep','-l','-F','-I',v,'HEAD','--'],capture_output=True,text=True).stdout.strip()
        if h: hits+=1; print("HEAD HIT",sorted(src),"->",[x.replace(r+'/','') for x in h.splitlines()][:3], r.replace(DEV+'/',''))
        lg=subprocess.run(['git','-C',r,'log','--all','--format=%h %cs','-S',v],capture_output=True,text=True).stdout.strip()
        if lg: hits+=1; print("HISTORY HIT",sorted(src),"in",r.replace(DEV+'/',''),"commits:",lg.splitlines()[:3])
print("hits",hits)
EOF
